abhinav_5_6 = {
    'hi': '।।6.5--6.6।। श्री अभिनवगुप्त कहते हैं: अपने द्वारा अपना उद्धार करे, अपने को गिराए नहीं; क्योंकि आत्मा ही अपना बन्धु (मित्र) है और आत्मा ही अपना रिपु (शत्रु) है। जिसने अपने आप से अपने आप को जीत लिया है, उसकी आत्मा ही उसका बन्धु है; किंतु जो अजितात्मा है, उसकी आत्मा ही उसके लिए शत्रुता में वर्तती है।',
    'en': '6.5--6.6 Sri Abhinavagupta states: Let a man elevate himself by his own Self, let him not degrade himself; for the Self alone is the friend of oneself, and the Self alone is one\"s enemy. The Self is the friend of him who has conquered himself by the Self; but for him who has not conquered himself, his own Self acts as an enemy in enmity.',
    'be': '৬.৫--৬.৬ শ্রী অভিনবগুপ্ত বলেছেন: নিজের দ্বারা নিজের উদ্ধার করুক, নিজেকে ফেলুক না; কারণ আত্মা ই নিজের বন্ধু (মিত্র) এবং আত্মা ই নিজের রিপু (শত্রু)। যে নিজের থেকে নিজেকে জিতে নিয়েছে, তার আত্মা ই তার বন্ধু; কিন্তু যে অজিতাত্মা, তার আত্মা ই তার জন্য শত্রুতার মধ্যে থাকে।',
    'ka': '೬.೫--೬.೬ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ತನ್ನಿಂದಲೇ ತನ್ನ ಉದ್ಧಾರವನ್ನು ಮಾಡಿಕೊಳ್ಳಬೇಕು, ತನ್ನನ್ನು ಕೆಳಗೆ ಬೀಳಿಸಿಕೊಳ್ಳಬಾರದು; ಏಕೆಂದರೆ ಆತ್ಮಾನೇ ತನ್ನ ಬಂಧು (ಮಿತ್ರ) ಹಾಗೂ ಆತ್ಮಾನೇ ತನ್ನ ರಿಪು (ಶತ್ರು). ಯಾರು ತನ್ನಿಂದ ತನ್ನನ್ನು ಗೆದ್ದುಕೊಂಡಿದ್ದಾನೋ, ಆತನ ಆತ್ಮಾನೇ ಆತನ ಬಂಧು; ಆದರೆ ಯಾರು ಅಜಿತಾತ್ಮನೋ, ಆತನ ಆತ್ಮಾನೇ ಆತನಿಗೆ ಶತ್ರುತ್ವದಲ್ಲಿ ವರ್ತಿಸುತ್ತದೆ'
}

abhinav_7_8 = {
    'hi': '।।6.7--6.8।। श्री अभिनवगुप्त कहते हैं: जिसने अपने आप को जीत लिया है और जो परम शान्त है, उसका परमात्मा (परम स्वरूप) सर्दी-गर्मी, सुख-दुःख और मान-अपमान में सदा समाहित (अविचल) रहता है। जिसका चित्त ज्ञान और विज्ञान से तृप्त है, जो कूटस्थ (निर्विकार) और विजितेन्द्रिय है, जिसके लिए मिट्टी का ढेला, पत्थर और स्वर्ण समान हैं, वह योगी पूर्णतया समाहित (युक्त) कहलाता है।',
    'en': '6.7--6.8 Sri Abhinavagupta states: The Supreme Self of him who has conquered himself and is deeply tranquil remains perfectly steadfast amid heat and cold, pleasure and pain, honor and dishonor. The Yogi whose mind is satisfied with spiritual knowledge and realization, who is unwavering and master of his senses, to whom a clod of earth, a stone, and gold are equal, is said to be fully integrated.',
    'be': '৬.৭--৬.৮ শ্রী অভিনবগুপ্ত বলেছেন: যে নিজের আপনাকে জিতে নিয়েছে এবং যে পরম শান্ত, তার পরমাত্মা (পরম রূপ) শীত-গ্রীষ্ম, সুখ-দুঃখ এবং মান-অপমানে সদা সমাহিত (অবিচল) থাকে। যার চিত্ত জ্ঞান ও বিজ্ঞান থেকে তৃপ্ত, যে কূটস্থ (নির্বিকার) ও বিজিতেন্দ্রিয়, যার জন্য মাটির ঢেল, পাথর ও সোনা সমান, সে যোগী পূর্ণত সমাহিত (যুক্ত) বলা হয়।',
    'ka': '೬.೭--೬.೮ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯಾರು ತನ್ನನ್ನು ಗೆದ್ದುಕೊಂಡಿದ್ದಾನೋ ಹಾಗೂ ಪರಮಶಾಂತನಾಗಿದ್ದಾನೋ, ಆತನ ಪರಮಾತ್ಮನು (ಪರಮಸ್ವರೂಪ) ಶೀತೋಷ್ಣ, ಸುಖದುಃಖ ಹಾಗೂ ಮಾನಾಪಮಾನಗಳಲ್ಲಿ ಸರ್ವದಾ ಸಮಾಹಿತನಾಗಿರುತ್ತಾನೆ (ಅವಿಚಲ). ಯಾರ ಚಿತ್ತವು ಜ್ಞಾನವಿಜ್ಞಾನಗಳಿಂದ ತೃಪ್ತವಾಗಿದೆಯೋ, ಯಾರು ಕಷ್ಟನೂ (ನಿರ್ವಿಕಾರ) ವಿಜಿತೇಂದ್ರಿಯನೂ ಆಗಿದ್ದಾನೋ, ಯಾರಿಗೆ ಮಣ್ಣಿನ ಹೆಂಟೆ, ಕಲ್ಲು ಹಾಗೂ ಸುವರ್ಣಗಳು ಸಮಾನವೋ, ಆ ಯೋಗಿಯು ಪೂರ್ಣವಾಗಿ ಸಮಾಹಿತನೆನಿಸಿಕೊಳ್ಳುತ್ತಾನೆ'
}

abhinav_10_12 = {
    'hi': '।।6.10--6.12।। श्री अभिनवगुप्त कहते हैं: योगी अकेला एकान्त स्थान में स्थित होकर, मन और शरीर को वश में रखते हुए, आशा और परिग्रह से रहित होकर सदा आत्मा में ध्यान लगाए। पवित्र स्थान में न अत्यन्त ऊँचा और न अत्यन्त नीचा, कुशा, मृगछाला और वस्त्र से ढका हुआ स्थिर आसन स्थापित करे। वहाँ एकाग्र मन करके, चित्त और इन्द्रियों की क्रियाओं को वश में रखते हुए, अन्तःकरण की शुद्धि के लिए योग का अभ्यास करे।',
    'en': '6.10--6.12 Sri Abhinavagupta states: Remaining in solitude, alone, with body and mind controlled, free from desire and possessions, let the Yogi constantly engage his mind in meditation. In a clean spot, establishing a firm seat neither too high nor too low, covered with Kusa grass, a deer skin, and a cloth, making the mind one-pointed and mastering thought and sense, let him practice Yoga for self-purification.',
    'be': '৬.১০--৬.১২ শ্রী অভিনবগুপ্ত বলেছেন: যোগী একা একান্ত স্থানে স্থিত হয়ে, মন ও শরীরকে বশে রেখে, আশা ও পরিগ্রহ থেকে রহিত হয়ে সদা আত্মায় ধ্যান লাগাক। পবিত্র স্থানে না অত্যন্ত উঁচু এবং না অত্যন্ত নিচু, কুশ, মৃগছাল ও কাপড়ে ঢাকা স্থির আসন স্থাপিত করুক। সেখানে একাগ্র মন করে, চিত্ত ও ইন্দ্রিয়ের ক্রিয়াগুলোকে বশে রেখে, অন্তঃকরণের শুদ্ধির জন্য যোগের অভ্যাস করুক।',
    'ka': '೬.೧೦--೬.೧೨ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯೋಗಿಯು ಏಕಾಂತಸ್ಥಾನದಲ್ಲಿ ಒಬ್ಬಂಟಿಗನಾಗಿ ನೆಲೆಸಿ, ಮನಸ್ಸು ಹಾಗೂ ಶರೀರಗಳನ್ನು ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡು, ಆಶೆಯೂ ಪರಿಗ್ರಹವೂ ಇಲ್ಲದವನಾಗಿ ಸರ್ವದಾ ಆತ್ಮನಲ್ಲಿ ಧ್ಯಾನವನ್ನು ಮಾಡಲಿ. ಪವಿತ್ರವಾದ ಸ್ಥಳದಲ್ಲಿ ಅತಿಯಾಗಿ ಎತ್ತರವೂ ಅಲ್ಲದ ಅತಿಯಾಗಿ ತಗ್ಗ ಇಲ್ಲದ, ಕುಶ, ಮೃಗಚರ್ಮ ಹಾಗೂ ವಸ್ತ್ರಗಳಿಂದ ಮುಚ್ಚಲ್ಪಟ್ಟ ಸ್ಥಿರವಾದ ಆಸನವನ್ನು ಸ್ಥಾಪಿಸಲಿ. ಅಲ್ಲಿ ಮನಸ್ಸನ್ನು ಏಕಾಗ್ರಗೊಳಿಸಿ, ಚಿತ್ತೇಂದ್ರಿಯಗಳ ಕ್ರಿಯೆಗಳನ್ನು ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡು, ಅಂತಃಕರಣಶುದ್ಧಿಗಾಗಿ ಯೋಗಾಭ್ಯಾಸವನ್ನು ಮಾಡಲಿ'
}

